// GitHub review latency (#402) — histogram of PR open-to-merge duration with a median callout.
// Extracted from GitHubPulse's inline card into its own composable record; adds the loading skeleton
// the inline version didn't have.
import { CardHead, Bars, useTip } from "@/shared/ui/charts";
import { SkeletonChart } from "@/shared/ui/feedback/Skeleton";
import { Box } from "@/shared/ui/layout/Box";
import { Card } from "@/shared/ui/data/Card";

const DEMO_BUCKETS = [{ label: "<1h", v: 4 }, { label: "1-4h", v: 6 }, { label: "4-12h", v: 5 }, { label: "12-24h", v: 3 }, { label: ">1d", v: 2 }];

export function ReviewLatency({ buckets = DEMO_BUCKETS, medianH = 5, loading = false }: { buckets?: Array<{ label: string; v: number }>; medianH?: number; loading?: boolean }) {
  const tip = useTip();
  const total = buckets.reduce((s, b) => s + b.v, 0);
  return (
    <Card>
      <CardHead title="Review latency" hint="PR open to merged · last 14d" />
      {loading ? <SkeletonChart height={116} /> : total === 0 ? (
        <Box className="hint" pad={[8, 2]}>No merged PRs in the window.</Box>
      ) : (
        <>
          <Bars labels={buckets.map((b) => b.label)} height={116} tip={tip} groups={[{ name: "PRs", color: "var(--info)", data: buckets.map((b) => b.v) }]} />
          <Box className="mono" style={{ marginTop: 6, fontSize: 10, color: "var(--fg-dim)", textAlign: "center" }}>
            median <b style={{ color: "var(--fg)" }}>{medianH}h</b> over {total} merged PR{total === 1 ? "" : "s"}
          </Box>
        </>
      )}
      {tip.node}
    </Card>
  );
}
